"""Aufbauplaner-Plugin: Übersetzungen und Hilfe.

T(text) übersetzt einen deutschen Oberflächentext in die Sprache, die BMC-Steward beim Laden des Plugins
meldet (api.lang). Fehlt ein Text hier, gilt die Übersetzung des Programms, sonst bleibt er deutsch.
"""

LANG = "de"
LANGS = ("en", "fr", "gsw")


def set_lang(code):
    global LANG
    LANG = code if code in LANGS else "de"


def T(text):
    if LANG == "de":
        return text
    hit = TR.get(text)
    if hit:
        return hit[LANGS.index(LANG)]
    try:                                    # gemeinsame Texte (Abbrechen, Speichern …) aus dem Programm
        from bmc_steward.i18n import T as app_t
    except ImportError:
        return text
    return app_t(text)


def help_html():
    """Hilfe des Plugins in der gewählten Sprache (HTML)."""
    return HELP.get(LANG) or HELP["de"]


